//
//  Depth of Field (Bokeh)
//  Native Metal Shader - Camera-like Focus
//

#include <metal_stdlib>
using namespace metal;

struct Uniforms {
    float4x4 MVP;
    float4 OutputSize;
    float4 SourceSize;
    float4 OriginalSize;
    uint FrameCount;
    float focus_distance;
    float aperture;
    float focal_length;
    float bokeh_shape;
};

struct VertexIn {
    float4 position [[attribute(0)]];
    float2 texCoord [[attribute(1)]];
};

struct VertexOut {
    float4 position [[position]];
    float2 texCoord;
};

vertex VertexOut main0(
    VertexIn in [[stage_in]],
    constant Uniforms &uniforms [[buffer(0)]]
)
{
    VertexOut out;
    out.position = uniforms.MVP * in.position;
    out.texCoord = in.texCoord;
    return out;
}

// Pseudo-depth from luminance and position
float getDepth(float2 uv, float3 color) {
    float luminanceDepth = dot(color, float3(0.299, 0.587, 0.114));

    // Add radial depth component
    float2 center = float2(0.5, 0.5);
    float radialDepth = length(uv - center) * 0.5;

    return luminanceDepth * 0.7 + radialDepth * 0.3;
}

// Hexagonal bokeh shape
float hexagon(float2 p, float r) {
    const float3 k = float3(-0.866025404, 0.5, 0.577350269);
    p = abs(p);
    p -= 2.0 * min(dot(k.xy, p), 0.0) * k.xy;
    p -= float2(clamp(p.x, -k.z * r, k.z * r), r);
    return length(p) * sign(p.y);
}

fragment float4 fragment_main(
    VertexOut in [[stage_in]],
    texture2d<float> sourceTexture [[texture(0)]],
    constant Uniforms &uniforms [[buffer(0)]]
)
{
    constexpr sampler textureSampler(
        mag_filter::linear,
        min_filter::linear,
        address::clamp_to_edge
    );

    float4 centerColor = sourceTexture.sample(textureSampler, in.texCoord);
    float centerDepth = getDepth(in.texCoord, centerColor.rgb);

    // Calculate circle of confusion
    float depthDiff = abs(centerDepth - uniforms.focus_distance);
    float coc = depthDiff * uniforms.aperture * uniforms.focal_length;
    coc = clamp(coc, 0.0, 0.05);

    // If in focus, return original
    if (coc < 0.001) {
        return centerColor;
    }

    // Bokeh blur
    float3 result = float3(0.0);
    float totalWeight = 0.0;

    int samples = 16;
    float goldenAngle = 2.399963229728653; // Golden angle in radians

    for (int i = 0; i < samples; i++) {
        float angle = float(i) * goldenAngle;
        float radius = sqrt(float(i) / float(samples));

        float2 offset = float2(cos(angle), sin(angle)) * radius * coc;

        // Hexagonal bokeh shape
        float2 bokehCoord = offset / coc;
        float bokehMask = smoothstep(1.0, 0.9, hexagon(bokehCoord, 1.0));
        bokehMask = mix(1.0, bokehMask, uniforms.bokeh_shape);

        float3 sample = sourceTexture.sample(textureSampler, in.texCoord + offset).rgb;
        float sampleDepth = getDepth(in.texCoord + offset, sample);

        // Weight by depth similarity
        float depthWeight = exp(-abs(sampleDepth - centerDepth) * 10.0);
        float weight = bokehMask * depthWeight;

        result += sample * weight;
        totalWeight += weight;
    }

    result /= totalWeight;

    // Blend based on CoC
    float blendFactor = smoothstep(0.0, 0.01, coc);
    result = mix(centerColor.rgb, result, blendFactor);

    return float4(result, 1.0);
}

